//! Repository for PurchaseReceiptItem entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written PurchaseReceiptItem SQL
//! (4-layer rule: services orchestrate, repositories hold the SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<PurchaseReceiptItem, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use rust_decimal::Decimal;
use sqlx::{PgPool, Row};
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::PurchaseReceiptItem;

/// Table name for PurchaseReceiptItem entities
pub const TABLE_NAME: &str = "inventory.purchase_receipt_items";

/// Repository for PurchaseReceiptItem entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct PurchaseReceiptItemRepository(
    backbone_orm::GenericCrudRepository<PurchaseReceiptItem, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for PurchaseReceiptItemRepository {
    type Target = backbone_orm::GenericCrudRepository<PurchaseReceiptItem, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl PurchaseReceiptItemRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a receipt line insert writes. `amount` arrives already rounded.
pub struct NewReceiptItemRow {
    pub id: Uuid,
    pub receipt_id: Uuid,
    pub company_id: Uuid,
    pub item_id: Uuid,
    pub quantity: Decimal,
    pub rate: Decimal,
    pub amount: Decimal,
}

/// A receipt line as the submit path reads it: what arrived, and at what cost.
pub struct ReceiptItemRow {
    pub item_id: Uuid,
    pub quantity: Decimal,
    pub rate: Decimal,
}

/// Hand-written PurchaseReceiptItem SQL. Lives here per the module's 4-layer rule.
impl PurchaseReceiptItemRepository {
    /// Insert one receipt line. Takes the CALLER'S connection so it commits with its header; the
    /// caller has already bound the company on it — don't re-bind here.
    pub async fn insert_item(
        &self,
        conn: &mut sqlx::PgConnection,
        l: &NewReceiptItemRow,
    ) -> Result<(), sqlx::Error> {
        sqlx::query(
            r#"INSERT INTO inventory.purchase_receipt_items (id, receipt_id, company_id, item_id, quantity, rate, amount)
               VALUES ($1,$2,$3,$4,$5,$6,$7)"#,
        )
        .bind(l.id).bind(l.receipt_id).bind(l.company_id).bind(l.item_id).bind(l.quantity).bind(l.rate).bind(l.amount)
        .execute(conn)
        .await?;
        Ok(())
    }

    /// Read the live lines in `id` order — the order the movement applies them (and therefore the
    /// order `sle_no` is assigned in), so it must not change. The caller wraps this in
    /// `with_company_scope(Some(company))` (the company comes off the header) so the read passes the
    /// RLS fence (ADR-0008).
    pub async fn fetch_items(
        &self,
        pool: &PgPool,
        receipt_id: Uuid,
    ) -> Result<Vec<ReceiptItemRow>, sqlx::Error> {
        let rows = company_scope::fetch_all_rows_scoped(
            pool,
            sqlx::query(
                r#"SELECT item_id, quantity, rate FROM inventory.purchase_receipt_items
                   WHERE receipt_id=$1 AND (metadata->>'deleted_at') IS NULL ORDER BY id"#,
            )
            .bind(receipt_id),
        )
        .await?;
        Ok(rows.iter().map(|it| ReceiptItemRow {
            item_id: it.get("item_id"), quantity: it.get("quantity"), rate: it.get("rate"),
        }).collect())
    }
}

backbone_core::impl_crud_repository!(PurchaseReceiptItemRepository, PurchaseReceiptItem, soft_delete);
